from pathlib import Path
import json,hashlib,subprocess,datetime
R=Path.cwd()
def sha(p):return hashlib.sha256((R/p).read_bytes()).hexdigest()
def read(p):return json.loads((R/p).read_text(encoding='utf8'))
def git(*a):return subprocess.check_output(['git',*a])
qc=read('logs/protocol_lock/final_G3/package_qc.json');assert qc['status']=='PASS' and qc['protocol_status']=='PROTOCOL_LOCKED'
head=git('rev-parse','HEAD').decode().strip();assert head!='1fc660b3ce09dd2b23b6a05e0698903bf6060355'
assert not git('status','--porcelain').strip(),'Final receipt requires committed clean lock payload'
m=read('logs/protocol_lock/final_G3/lock_payload_manifest.json')
for row in m['files']:
 assert sha(row['path'])==row['sha256']
 assert hashlib.sha256(git('show',head+':'+row['path'])).hexdigest()==row['sha256']
